"""Build an honest forty-slot review from the active manifest, never from archived/rejected frames."""
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import base64,html,json
R=Path(__file__).resolve().parents[1];D=R/'docs/portfolio/review/menswear-full-production-2026-10-23'
data=json.loads((D/'PRODUCTION.json').read_text());looks=data['looks'];stats=data['statistics'];groups=['Casualwear','Activewear','Outerwear','Tailoring']
def font(n):return ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',n)
def encoded(p,mime='image/webp'):return 'data:'+mime+';base64,'+base64.b64encode(Path(p).read_bytes()).decode()
W=5260;H=3700;board=Image.new('RGB',(W,H),'white');draw=ImageDraw.Draw(board)
draw.text((80,38),'ABERBACH',font=font(52),fill='#171717');draw.text((80,108),'MENSWEAR 2026/2027 / ORIGINAL AI FASHION CONCEPTS',font=font(24),fill='#666')
draw.text((3300,50),f"{stats['completedLooks']}/40 LOOKS   {stats['acceptedActivePhotographs']}/120 VIEWS   {stats['completedMasters']}/40 MASTERS",font=font(24),fill='#222')
for row,cat in enumerate(groups):
 top=190+row*860;draw.text((80,top),f'0{row+1} / {cat.upper()}',font=font(28),fill='#222')
 for i,x in enumerate([x for x in looks if x['category']==cat]):
  left=80+i*512;y=top+52
  if x['front']:
   im=Image.open(R/x['front']['exportPath']).convert('RGB').resize((480,720),Image.Resampling.LANCZOS);board.paste(im,(left,y))
  else:
   draw.rectangle((left,y,left+480,y+720),fill='#f4f4f4');draw.text((left+25,y+325),'NOT PRODUCED',font=font(23),fill='#888')
  draw.line((left,y+730,left+480,y+730),fill='#ddd',width=2);draw.text((left,y+746),f"{x['position']:02d} / {x['concept']['name']}",font=font(21),fill='#222')
  product=x['productSubtype'];product=product if len(product)<42 else product[:39]+'…';draw.text((left,y+777),product,font=font(17),fill='#666')
  if not x['master']:draw.text((left,y+803),'INCOMPLETE',font=font(15),fill='#777')
draw.text((80,3655),'Selected photographs only. Native dimensions and hashes retained. Export panels 1800 x 2700; masters 5400 x 2700 are resampled. No physical manufacture claimed.',font=font(20),fill='#666')
board.save(D/'FORTY-LOOK-CONTACT-SHEET.jpg',quality=94,subsampling=0)
interactive=[];sections=[]
for cat in groups:
 cards=[]
 for x in [x for x in looks if x['category']==cat]:
  c=x['concept'];pictures={v:encoded(R/x[v]['previewPath']) for v in ('front','back','editorial') if x[v]}
  if x['master']:pictures['master']=encoded(R/Path(x['master']['path']).with_name('master-1800.webp'))
  interactive.append({'id':x['id'],'name':c['name'],'category':cat,'product':x['productSubtype'],'pictures':pictures,'fabric':c['fabric'],'construction':c.get('archivedOriginalSpecification',{}).get('designLanguage',c['silhouette']+'. '+c['seams']),'styling':c['styling'],'complete':bool(x['master'])})
  image=f'<img src="{pictures["front"]}" alt="{html.escape(c["name"]+" — "+x["productSubtype"])}" width="600" height="900" loading="lazy">' if x['front'] else '<span class="missing">Not produced</span>'
  cards.append(f'<figure><button class="look" data-look="{x["id"]}" aria-label="Inspect {html.escape(c["name"])}">{image}</button><figcaption><span class="number">{x["position"]:02d}</span><h3>{html.escape(c["name"])}</h3><p>{html.escape(x["productSubtype"])}</p><small>{"Front / Back / Editorial" if x["master"] else "Incomplete — "+", ".join(v for v in ("front","back","editorial") if not x[v])+" missing"}</small></figcaption></figure>')
 sections.append(f'<section id="{cat.lower()}" class="category"><div class="section-title"><h2>{cat}</h2><span>10 distinct looks</span></div><div class="grid">'+''.join(cards)+'</div></section>')
errors=[x for x in data['attempts'] if x['outcome']!='SELECTED'];errorhtml=''.join('<li><b>'+html.escape(x['look']+' / '+x['view']+' / '+x['outcome'])+'</b><p>'+html.escape(x.get('cause',x.get('notes','')))+ '</p></li>' for x in errors) or '<li>No failed or rejected attempts recorded.</li>'
fonts=R/'tests/fixtures/fonts';archivo=next(fonts.glob('k3kQo*.woff2'));inter=next(fonts.glob('UcC73*.woff2'))
css=f"@font-face{{font-family:Archivo;src:url({encoded(archivo,'font/woff2')})}}@font-face{{font-family:Inter;src:url({encoded(inter,'font/woff2')})}}"+'''
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fff;color:#191919;font:14px/1.55 Inter,Arial}main{max-width:1640px;margin:auto;padding:34px 40px 70px}.brand{font:600 34px Archivo;letter-spacing:-1px}.meta{display:flex;justify-content:space-between;align-items:center;gap:22px}.eyebrow{text-transform:uppercase;font-size:10px;letter-spacing:1.7px;color:#666}h1{font:500 clamp(34px,4.5vw,62px)/1.05 Archivo;letter-spacing:-1.7px;margin:34px 0 22px}header p{max-width:860px;color:#555}.counts{font:12px/1.8 Inter}.nav{display:flex;flex-wrap:wrap;gap:22px;margin:25px 0}a{color:inherit;text-underline-offset:4px}.category{border-top:1px solid #d8d8d8;padding-top:24px;margin-top:36px;scroll-margin-top:20px}.section-title{display:flex;justify-content:space-between;align-items:baseline;gap:20px}.section-title h2{font:500 34px Archivo;margin:0 0 22px}.section-title span{font-size:11px;color:#666}.grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:24px 18px}figure{margin:0;min-width:0}.look{display:block;width:100%;padding:0;border:0;background:white;cursor:zoom-in;aspect-ratio:2/3}.look img{width:100%;height:auto;display:block;aspect-ratio:2/3;object-fit:contain}.missing{display:grid;place-items:center;width:100%;height:100%;background:#f4f4f4;font-size:11px;color:#777}figcaption{border-top:1px solid #ddd;padding:12px 0 10px;position:relative}.number{float:right;font-size:10px;color:#777}h3{font:500 22px Archivo;margin:0 25px 5px 0}figcaption p{font-size:11px;margin:0 0 4px}small{font-size:9px;color:#666}.notes{border-top:1px solid #ddd;margin-top:45px;padding-top:25px;max-width:1050px}.notes h2{font:500 30px Archivo}.notes p{color:#555}.notes li{margin:18px 0;font-size:12px}.notes li p{margin:6px 0}footer{margin-top:35px;border-top:1px solid #ddd;padding-top:18px;font-size:11px;color:#666}button:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid #222;outline-offset:4px}dialog{border:1px solid #ccc;background:white;max-width:95vw;max-height:97vh;padding:16px 20px;overflow:auto}dialog::backdrop{background:#0009}.bar{display:flex;justify-content:space-between;align-items:center;gap:25px;font-size:12px}.bar button,.views button{border:0;background:white;padding:9px 12px;min-height:42px;font:11px Inter;cursor:pointer}.bar button{border:1px solid #bbb}.views{display:flex;justify-content:center;flex-wrap:wrap;margin:4px 0 10px;gap:5px}.views button[aria-pressed=true]{text-decoration:underline;text-underline-offset:5px}.portrait{display:block;width:auto;max-width:86vw;max-height:72vh;aspect-ratio:2/3;object-fit:contain;margin:auto}.portrait.master{aspect-ratio:2;max-width:min(88vw,1400px)}.details{font-size:11px;max-width:720px;margin:12px auto 0}.details p{margin:6px 0;color:#555}body.modal{overflow:hidden}
@media(max-width:1100px){main{padding:28px}.grid{grid-template-columns:repeat(5,minmax(0,1fr));gap:20px 12px}h3{font-size:20px}}@media(max-width:800px){.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 18px}.meta{align-items:start}.counts{max-width:200px;font-size:11px;text-align:right}.category{margin-top:28px}.section-title h2{font-size:29px}}@media(max-width:480px){main{padding:22px 18px 45px}.brand{font-size:27px}.counts{max-width:165px;font-size:9px}h1{font-size:36px;letter-spacing:-1px}header p{font-size:12px}.nav{gap:12px 20px;font-size:11px}.grid{gap:22px 12px}h3{font-size:21px}figcaption p{font-size:10px}dialog{padding:12px;max-width:96vw}.bar{font-size:11px}.portrait{max-height:67vh}.views button{font-size:10px;padding:8px}.section-title span{font-size:10px}.notes li{font-size:11px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{main{padding:0;max-width:none}header,.notes,footer{display:none}.category{margin:0;padding:0;border:0;break-before:page}.category:first-of-type{break-before:auto}.section-title h2{font-size:24px;margin-bottom:12px}.grid{grid-template-columns:repeat(5,1fr);gap:12px 18px}.look{cursor:default}figure{break-inside:avoid}h3{font-size:18px}figcaption{padding:7px 0}.category{break-after:page}dialog{display:none}}
'''
js="""const records=JSON.parse(document.querySelector('#records').textContent),dialog=document.querySelector('dialog'),photo=dialog.querySelector('img'),title=document.querySelector('#look-title'),buttons=[...dialog.querySelectorAll('[data-view]')];let record,opener;function show(v){if(!record.pictures[v])return;photo.src=record.pictures[v];photo.alt=record.name+' / '+v;photo.classList.toggle('master',v==='master');buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===v)))}for(const button of document.querySelectorAll('.look'))button.onclick=()=>{record=records.find(r=>r.id===button.dataset.look);if(!record.pictures.front)return;opener=button;title.textContent=record.category+' / '+record.name+' / '+record.product;for(const b of buttons)b.hidden=!record.pictures[b.dataset.view];document.querySelector('#fabric').textContent=record.fabric;document.querySelector('#construction').textContent=record.construction;document.querySelector('#styling').textContent=record.styling;show('front');dialog.showModal();document.body.classList.add('modal');document.querySelector('#close').focus()};for(const b of buttons)b.onclick=()=>show(b.dataset.view);document.querySelector('#close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{document.body.classList.remove('modal');opener?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const keys=['front','back','editorial'].filter(k=>record.pictures[k]),current=buttons.find(b=>b.getAttribute('aria-pressed')==='true')?.dataset.view,i=keys.indexOf(current);show(keys[(i+(e.key==='ArrowRight'?1:-1)+keys.length)%keys.length])});"""
body=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ABERBACH — Menswear full production</title><style>{css}</style><main><header><div class="meta"><span class="brand">ABERBACH</span><span class="counts">{stats['completedLooks']} / 40 complete looks<br>{stats['acceptedActivePhotographs']} / 120 selected photographs<br>{stats['completedMasters']} / 40 three-view masters</span></div><p class="eyebrow">Menswear 2026/2027 · original AI fashion concepts</p><h1>Four categories.<br>Forty distinct looks.</h1><p>Contemporary, commercially believable menswear. Every complete look has genuine Front, Back and Editorial photographs with one consistent adult model and outfit. Click a look to inspect each view or its assembled master.</p><nav class="nav">{''.join(f'<a href="#{g.lower()}">{g}</a>' for g in groups)}</nav></header>{''.join(sections)}<section class="notes"><h2>Production and provenance</h2><p>Selected under the owner's full autonomous-production authorization. Final personal artistic acceptance remains with the owner. These are original AI fashion concepts and visual explorations, with no physical manufacture, client history, pattern evidence or certified performance claimed. Natural young-adult commercial casting follows the product.</p><p>All native outputs remain unmodified with true dimensions and SHA256. Export panels are 1800 × 2700 and masters 5400 × 2700, uniformly resampled without garment cropping or stretching. The contact sheet and previews are not extra active photographs. Rejected, interrupted and archived unused outputs are excluded from selected counts.</p><p>Current plan and actual selected refinements are in PRODUCTION.json and COLLECTION-PLAN.md. Commercial research, dated 23 October 2026, is linked in the README. Research establishes category breadth rather than a proven 2027 forecast.</p><h2>Errors and recovery</h2><ol>{errorhtml}</ol><p>Working-branch integration only. Historical media, identities and credits remain preserved. Womenswear is unchanged. No merge or deployment.</p></section><footer>ABERBACH / Menswear 2026/2027 / Self-contained review — download and open locally.</footer></main><dialog aria-labelledby="look-title"><div class="bar"><span id="look-title"></span><button id="close">Close</button></div><nav class="views" aria-label="Photographic views"><button data-view="front">Front</button><button data-view="back">Back</button><button data-view="editorial">Editorial</button><button data-view="master">Three-view master</button></nav><img class="portrait" alt=""><details class="details"><summary>Proposed materials & construction</summary><p id="fabric"></p><p id="construction"></p><p id="styling"></p></details></dialog><script type="application/json" id="records">{json.dumps(interactive).replace('</','<\\/')}</script><script>{js}</script></html>'''
(D/'index.html').write_text(body)
md=['# ABERBACH — selected forty-look production plan\n\n','The full autonomous-production brief authorizes these four ten-look groups. Selected image observations supersede earlier proposal details where recorded. Final personal owner acceptance remains pending; no intermediate approval gates apply. Proposed fibres, weights and hidden construction are not physical development evidence.\n\n']
for cat in groups:
 md.append('## '+cat+'\n\n')
 for x in [x for x in looks if x['category']==cat]:
  c=x['concept'];md.append(f"### {x['position']:02d} · {c['name']} — {x['productSubtype']}\n\nID: `{x['id']}` · {x['status']}\n\n")
  for label,key in [('Silhouette and fit','silhouette'),('Fabric and proposed weight','fabric'),('Collar','collar'),('Shoulder','shoulder'),('Sleeves','sleeves'),('Seams','seams'),('Pockets','pockets'),('Waist','waist'),('Fastenings','fastenings'),('Hem','hem'),('Colour','colour'),('Styling','styling'),('Casting','casting'),('Editorial direction','editorial')]:md.append(f'- **{label}:** {c[key]}\n')
  if x.get('selectedDesignRefinements'):md.append('- **Visible refinements:** '+json.dumps(x['selectedDesignRefinements'],ensure_ascii=False)+'\n')
  if x.get('adoptedFromGeneratedConcept'):md.append('- **Reviewed reuse:** '+x['adoptedFromGeneratedConcept']+'; original native files and archived specifications preserved.\n')
  md.append('\n')
(D/'COLLECTION-PLAN.md').write_text(''.join(md));print('Built 40-slot contact sheet and portable review;',stats['completedLooks'],'complete looks')
